    $result = [UIntPtr]::Zero
    $sent = [VB3EnvironmentNotification]::SendMessageTimeout(
        [IntPtr]0xffff, 0x1a, [UIntPtr]::Zero, 'Environment',
        0x2, 1000, [ref]$result)
    return ($sent -ne [IntPtr]::Zero)
}
